package com.textswag.studio.collagefilters

class GlitchFilter :
    BaseGlitchGPUImageFilter("uniform mat4 uMVPMatrix;attribute vec4 position;\nattribute vec4 inputTextureCoordinate;\n \nvarying vec2 textureCoordinate;\n \nvoid main()\n{\n    gl_Position = uMVPMatrix * position;\n    textureCoordinate = inputTextureCoordinate.xy;\n}", "uniform highp vec2 inputSize;\nuniform highp float iTime;\nvarying highp vec2 textureCoordinate;\nuniform sampler2D inputImageTexture;\n\nhighp float random2d(highp vec2 n) {\n    return fract(sin(dot(n, vec2(12.9898, 4.1414))) * 437.585453);\n}\n\nhighp float randomRange (in highp vec2 seed, in highp float min, in highp float max) {\n    return min + random2d(seed) * (max - min);\n}\n\nhighp float insideRange(highp float v, highp float bottom, highp float top) {\n    return step(bottom, v) - step(top, v);\n}\n\nconst highp float AMT = 0.3;\nconst highp float SPEED = 0.03;\n\nvoid main()\n{\n    highp float time = floor(iTime * SPEED * 60.0);\n\n    highp vec2 uv = textureCoordinate;\n    highp vec2 fragCoord = uv * inputSize;\n\n    highp vec3 outCol = texture2D(inputImageTexture, uv).rgb;\n\n    highp float maxOffset = AMT/2.0;\n    for (highp float i = 0.0; i < 10.0 * AMT; i += 1.0) {\n        highp float sliceY = random2d(vec2(time , 23.450 + float(i)));\n        highp float sliceH = random2d(vec2(time , 90.350 + float(i))) * 0.25;\n        highp float hOffset = randomRange(vec2(time , 96.250 + float(i)), -maxOffset, maxOffset);\n        highp vec2 uvOff = uv;\n        uvOff.x += hOffset;\n        if (insideRange(uv.y, sliceY, fract(sliceY+sliceH)) == 1.0 ){\n            outCol = texture2D(inputImageTexture, uvOff).rgb;\n        }\n    }\n\n    gl_FragColor = vec4(outCol,1.0);\n}"), AdjustableFilter {
    override fun setAmount(amountValue: Float) {
        setTime(amountValue)
    }
}
